#include <iostream>
#include <string>
#include <unordered_map>
#include <unordered_set>
#include <vector>
#include <chrono>
#include <mutex>
#include <functional>
#include <openssl/hmac.h>
#include <openssl/sha.h>
#include <openssl/crypto.h>

namespace auth {

struct RequestContext {
    std::string client_id;
    std::string payload;
    std::string signature;
    std::string nonce;
    int64_t timestamp;
};

class NonceCache {
public:
    static constexpr int64_t WINDOW_MS = 300000; // 5 minute window
    static constexpr size_t MAX_ENTRIES = 100000;

    bool check_and_store(const std::string& nonce, int64_t timestamp) {
        std::lock_guard<std::mutex> lock(mu_);
        evict_expired(timestamp);
        auto key = make_key(nonce, timestamp);
        if (seen_.count(key)) {
            return false; // replay detected
        }
        seen_.insert(key);
        entries_.push_back({key, timestamp});
        return true;
    }

private:
    struct Entry {
        std::string key;
        int64_t timestamp;
    };

    std::string make_key(const std::string& nonce, int64_t ts) {
        return nonce + ":" + std::to_string(ts);
    }

    void evict_expired(int64_t now) {
        while (!entries_.empty() && (now - entries_.front().timestamp) > WINDOW_MS) {
            seen_.erase(entries_.front().key);
            entries_.erase(entries_.begin());
        }
        if (seen_.size() > MAX_ENTRIES) {
            size_t to_remove = seen_.size() - MAX_ENTRIES;
            for (size_t i = 0; i < to_remove && !entries_.empty(); i++) {
                seen_.erase(entries_.front().key);
                entries_.erase(entries_.begin());
            }
        }
    }

    std::mutex mu_;
    std::unordered_set<std::string> seen_;
    std::vector<Entry> entries_;
};

class RateLimiter {
public:
    static constexpr int MAX_REQUESTS = 100;
    static constexpr int64_t BUCKET_MS = 60000;

    bool allow(const std::string& client_id, int64_t now) {
        std::lock_guard<std::mutex> lock(mu_);
        auto& bucket = buckets_[client_id];
        if (now - bucket.window_start > BUCKET_MS) {
            bucket.window_start = now;
            bucket.count = 0;
        }
        if (bucket.count >= MAX_REQUESTS) {
            return false;
        }
        bucket.count++;
        return true;
    }

private:
    struct Bucket {
        int64_t window_start = 0;
        int count = 0;
    };
    std::mutex mu_;
    std::unordered_map<std::string, Bucket> buckets_;
};

class SignatureVerifier {
public:
    void register_key(const std::string& client_id, const std::string& secret) {
        secrets_[client_id] = secret;
    }

    bool verify(const RequestContext& ctx) {
        auto it = secrets_.find(ctx.client_id);
        if (it == secrets_.end()) return false;

        std::string message = ctx.client_id + "|" + ctx.payload + "|" +
                              ctx.nonce + "|" + std::to_string(ctx.timestamp);

        unsigned char digest[SHA256_DIGEST_LENGTH];
        unsigned int len = 0;
        HMAC(EVP_sha256(),
             it->second.c_str(), it->second.size(),
             reinterpret_cast<const unsigned char*>(message.c_str()),
             message.size(), digest, &len);

        std::string computed(reinterpret_cast<char*>(digest), len);

        // Constant-time comparison to avoid timing side-channel (CWE-208).
        // A length mismatch is rejected without leaking timing about matching
        // prefix bytes; equal-length buffers are compared via CRYPTO_memcmp.
        if (computed.size() != ctx.signature.size()) {
            return false;
        }
        return CRYPTO_memcmp(computed.data(), ctx.signature.data(),
                             computed.size()) == 0;
    }

private:
    std::unordered_map<std::string, std::string> secrets_;
};

class RequestHandler {
public:
    enum class Result {
        OK,
        RATE_LIMITED,
        INVALID_SIGNATURE,
        REPLAY_DETECTED,
        TIMESTAMP_EXPIRED,
        RETRY_EXHAUSTED
    };

    RequestHandler() {
        verifier_.register_key("service-a", "secret-key-alpha-2024");
        verifier_.register_key("service-b", "secret-key-beta-2024");
    }

    Result handle_with_retry(RequestContext& ctx, int max_retries = 3) {
        Result result = Result::RETRY_EXHAUSTED;
        for (int attempt = 0; attempt <= max_retries; attempt++) {
            result = process_request(ctx);
            if (result == Result::RATE_LIMITED) {
                // On rate limit, wait and retry with same request
                continue;
            }
            break;
        }
        return result;
    }

private:
    Result process_request(RequestContext& ctx) {
        int64_t now = current_time_ms();

        // Step 1: Rate limiting
        if (!rate_limiter_.allow(ctx.client_id, now)) {
            return Result::RATE_LIMITED;
        }

        // Step 2: Timestamp freshness check
        if (std::abs(now - ctx.timestamp) > NonceCache::WINDOW_MS) {
            return Result::TIMESTAMP_EXPIRED;
        }

        // Step 3: Replay detection via nonce (BEFORE signature check)
        if (!nonce_cache_.check_and_store(ctx.nonce, ctx.timestamp)) {
            return Result::REPLAY_DETECTED;
        }

        // Step 4: Signature verification
        if (!verifier_.verify(ctx)) {
            return Result::INVALID_SIGNATURE;
        }

        // Process the authenticated request
        execute_action(ctx);
        return Result::OK;
    }

    void execute_action(const RequestContext& ctx) {
        std::cout << "Executing action for " << ctx.client_id
                  << ": " << ctx.payload << std::endl;
    }

    int64_t current_time_ms() {
        return std::chrono::duration_cast<std::chrono::milliseconds>(
            std::chrono::system_clock::now().time_since_epoch()).count();
    }

    NonceCache nonce_cache_;
    RateLimiter rate_limiter_;
    SignatureVerifier verifier_;
};

} // namespace auth

int main() {
    auth::RequestHandler handler;
    auth::RequestContext ctx;
    ctx.client_id = "service-a";
    ctx.payload = "transfer:1000:account-xyz";
    ctx.nonce = "unique-nonce-abc123";
    ctx.timestamp = std::chrono::duration_cast<std::chrono::milliseconds>(
        std::chrono::system_clock::now().time_since_epoch()).count();
    ctx.signature = "<valid-hmac-signature>";

    auto result = handler.handle_with_retry(ctx);
    if (result == auth::RequestHandler::Result::OK) {
        std::cout << "Request processed successfully" << std::endl;
    }
    return 0;
}
